package com.shubhasai.monkeymart.data

import android.content.Context
import android.net.ConnectivityManager
import android.net.NetworkCapabilities
import kotlinx.coroutines.delay
import java.io.IOException
import kotlin.random.Random

data class OrderRequest(
    val productId: Int,
    val name: String,
    val email: String,
    val phone: String,
    val address: String,
    val city: String,
    val pincode: String,
)

/** Talks to the (fake) orders backend. Needs a working network connection, like the real one. */
class OrderRepository(context: Context) {

    private val connectivity = context.applicationContext.getSystemService(ConnectivityManager::class.java)

    /** Places the order and returns its id. */
    suspend fun submit(order: OrderRequest): String {
        if (!isOnline()) throw IOException("Unable to reach orders.monkeymart.example: no network")
        delay(1_500)
        return "MM-%06d".format(Random.nextInt(1_000_000))
    }

    private fun isOnline(): Boolean {
        val caps = connectivity.getNetworkCapabilities(connectivity.activeNetwork) ?: return false
        return caps.hasCapability(NetworkCapabilities.NET_CAPABILITY_INTERNET)
    }
}

package com.shubhasai.monkeymart.ui

import androidx.compose.runtime.getValue
import androidx.compose.runtime.mutableStateOf
import androidx.compose.runtime.setValue
import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import com.shubhasai.monkeymart.data.OrderRepository
import com.shubhasai.monkeymart.data.OrderRequest
import kotlinx.coroutines.launch

/** Holds the checkout form while the user fills it in. */
class CheckoutViewModel : ViewModel() {
    var name by mutableStateOf("")
    var email by mutableStateOf("")
    var phone by mutableStateOf("")
    var address by mutableStateOf("")
    var city by mutableStateOf("")
    var pincode by mutableStateOf("")

    var placing by mutableStateOf(false)
        private set
    var orderId by mutableStateOf<String?>(null)
        private set

    val isComplete: Boolean
        get() = listOf(name, email, phone, address, city, pincode).all { it.isNotBlank() }

    fun placeOrder(orders: OrderRepository, productId: Int) {
        placing = true
        viewModelScope.launch {
            orderId = orders.submit(OrderRequest(productId, name, email, phone, address, city, pincode))
            placing = false
        }
    }
}

